             },
             'mounted'(node) {
               const methods = getNodeMethods(node);
               checkStateMethods(context, methods, 'mounted');
             },
             'beforeUpdate'(node) {
               const methods = getNodeMethods(node);
               checkStateMethods(context, methods, 'beforeUpdate');
             },
             'updated'(node) {
               const methods = getNodeMethods(node);
               checkStateMethods(context, methods, 'updated');
             },
             'beforeDestroy'(node) {
               const methods = getNodeMethods(node);
               checkStateMethods(context, methods, 'beforeDestroy');
             },
             'destroyed'(node) {
               const methods = getNodeMethods(node);
               checkStateMethods(context, methods, 'destroyed');
             },
           };
         },
