   use Laravel\Dusk\Tasks;

   class MyTask extends Tasks
   {
       /**
        * Ejecuta una tarea de prueba.
        *
        * @return mixed
        */
       public function run()
       {
           $this->browse(function ($browser) {
               $browser->visit('/');

               // Agrega las pruebas de usuario aquí

               $this->assertSee('Home Page');
           });
       }
   }

   ```

10. Ejecuta las pruebas de Laravel Dusk:

   ```bash
   php artisan dusk
   ```

